-- Titles and descriptions of the tracks, given when publishing them on the sample website (site/);
-- the backend stores none
CREATE TABLE IF NOT EXISTS "LOCAL_TRACK_DETAILS" (
    "TRACKID" INTEGER PRIMARY KEY REFERENCES "TRACKS" ("ID"),
    "TITLE" TEXT NOT NULL,
    "DESCRIPTION" TEXT NOT NULL
);

INSERT INTO "LOCAL_TRACK_DETAILS" ("TRACKID", "TITLE", "DESCRIPTION") VALUES
    (1, 'First ride', 'A gentle start: clear the jump, take the checkpoint and reach the target.'),
    (2, 'Linked checkpoints', 'Ride the boost, then take either checkpoint of the linked pair.'),
    (3, 'Hills', 'Rolling hills to climb, behind a row of foreground posts.'),
    (4, 'Command blocks', 'Blocks that zoom, show the way, open a door, make a bridge appear and slide a door up as you ride over them. Doors only open for the riders who touched their block.');
